
CREATE TABLE IF NOT EXISTS topics (
 id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS sources (
 id TEXT PRIMARY KEY, title TEXT NOT NULL, publisher TEXT NOT NULL,
 url TEXT NOT NULL UNIQUE, published_on TEXT, verified_on TEXT,
 verification TEXT NOT NULL CHECK(verification IN ('verified','unread','needs_review'))
);
CREATE TABLE IF NOT EXISTS projects (
 id TEXT PRIMARY KEY, title TEXT NOT NULL, summary TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('proposed','consultation','approved','early_works','under_construction','completed','paused','cancelled','unknown')),
 location TEXT NOT NULL, cbd_relevance TEXT NOT NULL,
 latitude REAL CHECK(latitude BETWEEN -90 AND 90),
 longitude REAL CHECK(longitude BETWEEN -180 AND 180),
 geometry_geojson TEXT,
 source_id TEXT NOT NULL REFERENCES sources(id), verified_on TEXT,
 CHECK((latitude IS NULL) = (longitude IS NULL))
);
CREATE TABLE IF NOT EXISTS project_topics (
 project_id TEXT REFERENCES projects(id), topic_id TEXT REFERENCES topics(id),
 PRIMARY KEY(project_id,topic_id)
);
CREATE TABLE IF NOT EXISTS stages (
 id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id),
 position INTEGER NOT NULL CHECK(position > 0), title TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('planned','underway','completed','paused','cancelled','unknown')),
 planned_start TEXT, planned_end TEXT, actual_start TEXT, actual_end TEXT,
 date_precision TEXT NOT NULL CHECK(date_precision IN ('day','month','year','unknown')),
 summary TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id), verified_on TEXT,
 UNIQUE(project_id,position)
);
CREATE TABLE IF NOT EXISTS news (
 id TEXT PRIMARY KEY, title TEXT NOT NULL, summary TEXT NOT NULL,
 source_id TEXT NOT NULL REFERENCES sources(id),
 location TEXT NOT NULL, cbd_relevance TEXT NOT NULL,
 review_status TEXT NOT NULL CHECK(review_status IN ('draft','reviewed','rejected'))
);
CREATE TABLE IF NOT EXISTS news_topics (
 news_id TEXT REFERENCES news(id), topic_id TEXT REFERENCES topics(id), PRIMARY KEY(news_id,topic_id)
);
CREATE TABLE IF NOT EXISTS news_projects (
 news_id TEXT REFERENCES news(id), project_id TEXT REFERENCES projects(id), PRIMARY KEY(news_id,project_id)
);
CREATE INDEX IF NOT EXISTS stages_project ON stages(project_id,position);
CREATE INDEX IF NOT EXISTS news_source ON news(source_id);
CREATE TABLE IF NOT EXISTS project_answers (
 project_id TEXT NOT NULL REFERENCES projects(id),
 question_id TEXT NOT NULL CHECK(question_id IN ('overview','location','stages','timing','news','sources')),
 title TEXT NOT NULL, body TEXT NOT NULL CHECK(length(trim(body)) >= 80),
 source_id TEXT NOT NULL REFERENCES sources(id), verified_on TEXT NOT NULL,
 PRIMARY KEY(project_id,question_id)
);
CREATE TABLE IF NOT EXISTS plan_maps (
 id TEXT PRIMARY KEY, plan_id TEXT NOT NULL, title TEXT NOT NULL,
 image_url TEXT NOT NULL, caption TEXT NOT NULL, alt_text TEXT NOT NULL,
 source_id TEXT NOT NULL REFERENCES sources(id), verified_on TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS plan_maps_plan ON plan_maps(plan_id);

