INSERT INTO projects (id,title,summary,status,location,cbd_relevance,latitude,longitude,geometry_geojson,source_id,verified_on) VALUES ('melbourne-airport-rail','Melbourne Airport Rail','Rail infrastructure delivered in separate stages. Stage completion dates do not establish an opening date for the full airport connection.','under_construction','Western Melbourne rail corridor','Indirect: rail connections to the CBD via the Metro Tunnel; works are outside the CBD.',NULL,NULL,NULL,'airport-rail','2026-10-05');
INSERT INTO projects (id,title,summary,status,location,cbd_relevance,latitude,longitude,geometry_geojson,source_id,verified_on) VALUES ('gurrowa-place','Gurrowa Place','Housing, student accommodation, heritage restoration and a new Market Square. Current construction stage is not confirmed by the reviewed overview.','unknown','South of Queen Victoria Market','Direct: housing and public space in the market precinct.',NULL,NULL,NULL,'gurrowa','2026-10-05');
INSERT INTO projects (id,title,summary,status,location,cbd_relevance,latitude,longitude,geometry_geojson,source_id,verified_on) VALUES ('greenline','Greenline','Riverfront renewal with one section delivered and further sections in planning.','approved','North bank of the Yarra, Birrarung Marr to Victoria Harbour','Direct: riverfront public space alongside the CBD.',NULL,NULL,NULL,'greenline','2026-10-05');
INSERT INTO projects (id,title,summary,status,location,cbd_relevance,latitude,longitude,geometry_geojson,source_id,verified_on) VALUES ('franklin-street','Franklin Street transformation','Street redesign connecting the market and CBD; initial road works are complete and Stage 2 is planned.','approved','Franklin Street, Peel Street to Stewart Street','Direct: cycling, walking and access between the CBD and market.',NULL,NULL,NULL,'franklin','2026-10-05');
INSERT INTO projects (id,title,summary,status,location,cbd_relevance,latitude,longitude,geometry_geojson,source_id,verified_on) VALUES ('town-hall-finishing','Town Hall Station finishing works','Federation Square entrance construction and surface reinstatement remain after major station construction.','under_construction','Federation Square, Flinders Street','Direct: access to Town Hall Station and the CBD riverfront.',NULL,NULL,NULL,'town-hall-works','2026-10-05');
INSERT INTO projects (id,title,summary,status,location,cbd_relevance,latitude,longitude,geometry_geojson,source_id,verified_on) VALUES ('town-hall-overstation','Town Hall Place','Lendlease’s commercial overstation development with office, retail and laneway connections above Town Hall Station.','under_construction','Town Hall Station, Melbourne CBD','Direct: development above a CBD station.',NULL,NULL,NULL,'town-hall-works','2026-10-05');
INSERT INTO projects (id,title,summary,status,location,cbd_relevance,latitude,longitude,geometry_geojson,source_id,verified_on) VALUES ('state-library-overstation','State Library Exchange','Scape’s overstation development combining student accommodation with education, retail and commercial space; target completion early 2029.','under_construction','State Library Station, Melbourne CBD','Direct: development above a CBD station.',NULL,NULL,NULL,'state-library-exchange','2026-10-05');
