INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('central-city-urban-forest','overview','What the plan changes','This plan guides the Central City’s street trees over 2025–2035. It prioritises streets with little canopy, supports new trees as they grow and protects older avenues. The aim is a healthier urban forest, rather than replacing every street at once.','forest-part-b','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('central-city-urban-forest','location','Where it fits into the city','The plan covers Central City streets. Its maps compare canopy cover and planting needs street by street. A street with few trees and no recent planting receives different attention from an established avenue or a street where young trees are already growing.','forest-part-b','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('central-city-urban-forest','stages','Completed work and next steps','The plan organises work into planting, growing and caring for trees. Low-canopy streets without recent planting are prioritised for new trees; recent plantings are monitored; older avenues receive care. Approval alone does not confirm which individual street works have finished.','forest-part-b','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('central-city-urban-forest','timing','The timeline explained','The planting map groups priorities into years 1–4, 5–7 and 8–10 of the plan. New trees receive three years of maintenance. The plan also targets assessment of all Central City streetscapes for planting potential by 2032; individual works can move around other projects.','forest-part-b','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('central-city-urban-forest','news','Updates we have checked','The plan was endorsed on 18 March 2025 after community input. Its next steps are street-level planting, monitoring growth and caring for mature trees. We have not verified a live planting completion report, so these priorities are not presented as completed works.','forest-endorsement','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('central-city-urban-forest','sources','What you will find in the original plan','Part B explains existing canopy, tree diversity and the planting approach. Map 8 groups streets by planting priority and tree-care needs. Use it to understand a street’s planned treatment; it is not a live works calendar or a prediction of its future temperature.','forest-part-b','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('greenline','overview','What the plan changes','Greenline connects promenades, parks, planting and public spaces along the Yarra’s north bank. Delivery is staged: the Birrarung Marr section is complete, while other stretches remain in planning. The whole riverfront project is not finished.','greenline','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('greenline','location','Where it fits into the city','The project runs beside the CBD from Birrarung Marr towards Victoria Harbour. It links riverfront destinations with surrounding streets, giving people places to walk and spend time near the city centre.','greenline','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('greenline','stages','Completed work and next steps','Birrarung Marr Site 1 was delivered in December 2025. Further riverfront plans are being developed, including sections towards the aquarium. A finished first section should not be read as completion of all Greenline precincts.','greenline','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('greenline','timing','The timeline explained','The first section opened in December 2025. The older implementation plan indicated delivery through 2028, subject to approvals. That indicative date does not establish a confirmed opening date for every remaining section.','greenline','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('greenline','news','Updates we have checked','Council reports a completed 450-metre first section and funding for planning subsequent sections. This is a progress update: it does not mean every future precinct has funding or a final construction schedule.','greenline','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('greenline','sources','What you will find in the original plan','Council’s project page includes the master plan, engagement findings and a timeline. The master plan explains the intended connections; the current progress text distinguishes the completed section from planning still underway.','greenline','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('franklin-street','overview','What the plan changes','Franklin Street is being redesigned to improve walking, cycling and public space between the market and CBD. The design includes protected bike lanes, wider pedestrian space and planting, while retaining traffic in both directions.','franklin','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('franklin-street','location','Where it fits into the city','The two stages cover Peel Street to Queen Street, then Queen Street to Stewart Street. The route is important because it connects Queen Victoria Market with central-city streets and the neighbouring Gurrowa Place precinct.','franklin','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('franklin-street','stages','Completed work and next steps','Roundabout removal and road realignment finished in May 2024. Stage 2’s concept was endorsed in September 2024. Pathways and signals associated with the first stage still depend on Gurrowa Place; the initial road works are not the entire transformation.','franklin','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('franklin-street','timing','The timeline explained','Council currently lists Stage 2 construction for early 2027. Some first-stage finishing works are tied to completion of Gurrowa Place. An exact start day and final opening date are not confirmed in the reviewed material.','franklin','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('franklin-street','news','Updates we have checked','The source now lists an endorsed Stage 2 design and early-2027 construction. This places the next street transformation after the completed road realignment; it should not be described as already delivered.','franklin','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('franklin-street','sources','What you will find in the original plan','Council’s page explains both stages, the design changes and their sequencing. It is especially useful for distinguishing finished road realignment from future streetscape works and the finishing work dependent on Gurrowa Place.','franklin','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('gurrowa-place','overview','What the plan changes','Gurrowa Place combines new housing and student accommodation with heritage restoration and public space. The developer describes three buildings, restoration of the Franklin Street Stores and a new Market Square as parts of the precinct.','gurrowa','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('gurrowa-place','location','Where it fits into the city','The precinct is south of Queen Victoria Market, on its existing car-park side. It connects new residential uses and public space with the market and surrounding CBD streets.','gurrowa','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('gurrowa-place','stages','Completed work and next steps','The reviewed overview identifies the precinct’s components, but does not confirm a construction-stage breakdown. We cannot reliably label demolition, foundations or tower construction as finished. Those stages remain unconfirmed rather than inferred from artist impressions.','gurrowa','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('gurrowa-place','timing','The timeline explained','The reviewed developer overview does not give a confirmed delivery timetable for each component. Market Square, heritage restoration and the buildings should therefore not be assigned one invented opening date.','gurrowa','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('gurrowa-place','news','Updates we have checked','The developer’s current overview describes housing, student accommodation, Franklin Street Stores restoration and Market Square. These are stated project components; the overview does not establish which construction milestones have been reached.','gurrowa','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('gurrowa-place','sources','What you will find in the original plan','The developer page explains the intended precinct, building uses and public-space components. Its images include design impressions. They illustrate proposals and should not be used as proof that construction or opening has occurred.','gurrowa','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('melbourne-airport-rail','overview','What the plan changes','Airport Rail is being delivered in stages. The first upgrades tracks and stations around Sunshine; the second adds a line towards Keilor East. These are steps towards an airport connection, rather than evidence of a complete airport service.','airport-rail','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('melbourne-airport-rail','location','Where it fits into the city','Stage 1 runs from West Footscray to Albion and Stage 2 from Albion to Keilor East. Works are outside the CBD, but the rail connections link with the Metro Tunnel and central-city travel.','airport-rail','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('melbourne-airport-rail','stages','Completed work and next steps','Stage 1 works are underway. Stage 2 investigations and development work are announced ahead of major construction. Finishing either stage does not by itself complete the airport link.','airport-rail','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('melbourne-airport-rail','timing','The timeline explained','Stage 1 is planned to finish in 2030. Stage 2 major construction is scheduled for 2028–2031. Those dates describe the published stages, not a confirmed opening date for the full airport service.','airport-rail','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('melbourne-airport-rail','news','Updates we have checked','The 30 September 2026 announcement advances Stage 2, with investigations and development work preceding major construction. Stage 1 remains a separate package already underway; the two stages should be followed independently.','airport-rail','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('melbourne-airport-rail','sources','What you will find in the original plan','Big Build separates the Stage 1 and Stage 2 scope, maps, timelines and news. Reading those separately helps distinguish track-capacity upgrades from new line construction and avoids mistaking a stage completion date for airport services starting.','airport-rail','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('town-hall-finishing','overview','What the plan changes','These works finish the Federation Square entrance to Town Hall Station and restore the surrounding surface. Major station construction is already complete; this record follows the remaining entrance and public-space works.','town-hall-works','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('town-hall-finishing','location','Where it fits into the city','The works are at Federation Square beside Flinders Street, providing another access point to Town Hall Station. They affect the station precinct and pedestrian space near the southern edge of the CBD.','town-hall-works','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('town-hall-finishing','stages','Completed work and next steps','Major station construction is complete. Entrance finishing and surface reinstatement remain in progress. Nearby overstation buildings are separate projects, so finishing the station precinct does not finish those developments.','town-hall-works','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('town-hall-finishing','timing','The timeline explained','The Federation Square entrance is planned to open in late 2026. Big Build also lists the eastern St Kilda Road crossing reopening in October 2026. These are published targets, rather than confirmation that either is already open.','town-hall-works','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('town-hall-finishing','news','Updates we have checked','Big Build reports continuing entrance and surface works. Portions of Federation Square may close temporarily for reinstatement. The station remains distinct from the separate building developments above the CBD stations.','town-hall-works','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('town-hall-finishing','sources','What you will find in the original plan','The current works page sets out the remaining station works, pedestrian impacts and construction notices. It helps identify entrance and public-space work, while explaining that nearby overstation buildings are outside the Metro Tunnel project.','town-hall-works','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('town-hall-overstation','overview','What the plan changes','Town Hall Place is a commercial development above the station entrance, with offices, retail and pedestrian connections. It adds building uses at a transport gateway, while the station itself is a separate operating facility.','town-hall-place','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('town-hall-overstation','location','Where it fits into the city','The building sits above the Swanston Street entrance near Flinders Street. The design connects with Scott and Cocker Alleys towards Flinders Lane, placing the development directly within the southern CBD.','town-hall-place','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('town-hall-overstation','stages','Completed work and next steps','Big Build reports construction of the overstation development separately from the station. We have not verified a detailed structural or fit-out milestone schedule. Town Hall Station is intended to remain open during the building works.','town-hall-works','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('town-hall-overstation','timing','The timeline explained','The reviewed developer page does not confirm a final opening date. Completion of the station, or a target for its Federation Square entrance, cannot be used as the completion date for this separate commercial building.','town-hall-place','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('town-hall-overstation','news','Updates we have checked','The developer presents office floors, retail and laneway connections; Big Build identifies Town Hall Place as Lendlease’s separate development. These sources explain its scope, but do not establish a new verified completion milestone.','town-hall-place','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('town-hall-overstation','sources','What you will find in the original plan','The Town Hall Place page explains the building’s commercial uses and intended laneway connections. Big Build’s overstation page explains its relationship to the station. Design impressions show intentions rather than proving an area is open.','town-hall-place','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('state-library-overstation','overview','What the plan changes','State Library Exchange combines student accommodation with retail, commercial and education space above State Library Station. Scape describes around 1,400 student beds and a partnership with RMIT, connecting living and learning in the CBD.','state-library-exchange','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('state-library-overstation','location','Where it fits into the city','The development is at 393 Swanston Street, above State Library Station near La Trobe Street. Its entrance is described on Literature Lane, between La Trobe and Little La Trobe streets.','state-library-exchange','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('state-library-overstation','stages','Completed work and next steps','Big Build reports the overstation building under construction and treats it separately from the station. The reviewed sources do not provide a completed-floor or fit-out schedule. The station is intended to stay open during development.','town-hall-works','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('state-library-overstation','timing','The timeline explained','Scape gives a target completion of early 2029. This is a developer target, not a confirmed opening or move-in date. It also does not mean station services must wait for the building to finish.','state-library-exchange','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('state-library-overstation','news','Updates we have checked','Scape’s overview describes the RMIT partnership, student accommodation and education space, with early 2029 as its target. This provides more detail than the transport project page, which mainly explains the separate overstation development.','state-library-exchange','2026-10-05');
INSERT INTO project_answers (project_id,question_id,title,body,source_id,verified_on) VALUES ('state-library-overstation','sources','What you will find in the original plan','Scape’s page sets out accommodation, education and commercial uses, the location and target completion. Big Build supplies the station relationship. Together they distinguish the building’s intended uses from the operating rail station below.','state-library-exchange','2026-10-05');
INSERT INTO plan_maps (id,plan_id,title,image_url,caption,alt_text,source_id,verified_on) VALUES ('forest-planting','central-city-urban-forest','Central City tree planting plan','data/plan-maps/urban-forest-planting-08.png','Map 8, printed page 31 of the 2025–2035 plan. Colours show planting priorities and areas to grow or care for trees; they do not show live completed works.','Official Central City street planting priority map with its plant, grow and care-for legend.','forest-part-b','2026-10-05');
INSERT INTO plan_maps (id,plan_id,title,image_url,caption,alt_text,source_id,verified_on) VALUES ('greenline-site-plan','greenline','Greenline overall site plan','https://hdp-au-prod-app-com-participate-files.s3.ap-southeast-2.amazonaws.com/6816/9162/2983/greenline-base-map-crop.png','Council’s overall site plan for the north bank of the Yarra–Birrarung. The plan includes completed and future precincts; this is not a live works map.','Official Greenline overall site plan along the northern river bank.','greenline','2026-10-05');
INSERT INTO plan_maps (id,plan_id,title,image_url,caption,alt_text,source_id,verified_on) VALUES ('airport-rail-route','melbourne-airport-rail','Melbourne Airport Rail project map','https://bigbuild.vic.gov.au/__data/assets/image/0020/1050608/MAR13088-MARS2-Overarching-Map-A4-V10-FA-1.jpg','Published with Big Build’s 30 September 2026 Stage 2 announcement. Shows the project route and stages, rather than an operating airport service.','Official Melbourne Airport Rail project route and stages map.','airport-stage-2-news','2026-10-05');
INSERT INTO plan_maps (id,plan_id,title,image_url,caption,alt_text,source_id,verified_on) VALUES ('transport-future-network','transport','Transport Strategy 2030 network concept','data/plan-maps/transport-strategy-map-42.png','Figure 28, printed page 81 of the strategy endorsed in 2019. This is the strategy’s historical future-network concept, not today’s operating network or a current project commitment.','Official 2019 Transport Strategy future rail network schematic and legend.','transport-strategy-document','2026-10-05');
INSERT INTO plan_maps (id,plan_id,title,image_url,caption,alt_text,source_id,verified_on) VALUES ('town-hall-precinct','town-hall-finishing','Town Hall Station precinct and entrances','https://bigbuild.vic.gov.au/__data/assets/image/0011/978113/MT-TownHall-Location.png','Official station location map, including the Federation Square entrance. Entrance opening notes belong to the published map; consult the current works notice for access today.','Official Town Hall Station precinct map showing entrances and surrounding streets.','town-hall-location','2026-10-05');
INSERT INTO plan_maps (id,plan_id,title,image_url,caption,alt_text,source_id,verified_on) VALUES ('town-hall-place-context','town-hall-overstation','Town Hall Place station context','https://bigbuild.vic.gov.au/__data/assets/image/0011/978113/MT-TownHall-Location.png','Station location map showing the Swanston Street entrance beneath the development. This is a precinct context map, not a building footprint or construction boundary.','Official Town Hall Station map providing location context for the overstation development.','town-hall-location','2026-10-05');
INSERT INTO plan_maps (id,plan_id,title,image_url,caption,alt_text,source_id,verified_on) VALUES ('library-exchange-context','state-library-overstation','State Library Exchange station context','https://bigbuild.vic.gov.au/__data/assets/image/0009/978111/MT-StateLibrary-Location.png','Station location map showing the Swanston/La Trobe entrance beneath the development. This is a precinct context map, not a building footprint or construction boundary.','Official State Library Station map providing location context for the overstation development.','library-location','2026-10-05');
